    omt_buf_append(out, "\n<h1>Network Settings</h1>\n<div class=\"content-grid\">\n    <section class=\"card\" aria-labelledby=\"discovery-heading\">\n        <h2 id=\"discovery-heading\">OMT discovery</h2>\n        <p>mDNS discovery remains enabled. Configure one optional Discovery Server for routed networks.</p>\n        ", 287);
