static void system_content(omt_buf *out, const tv_scope *scope) {
    (void)out;
    (void)scope;
    omt_buf_append(out, "\n<h1>System</h1>\n<section class=\"card\" aria-labelledby=\"video-limit-heading\">\n    <h2 id=\"video-limit-heading\">Video limit</h2>\n    <p>This appliance is a ", 155);
    tv_render(out, tv_attr(tv_lookup(scope, "video_limit"), "board_label"));
    omt_buf_append(out, ". It accepts video up to\n       <strong>", 40);
    tv_render(out, tv_attr(tv_lookup(scope, "video_limit"), "effective_description"));
    omt_buf_append(out, "</strong>.\n       Anything larger or faster is reported as an unsupported format rather than\n       being converted.</p>\n    ", 125);
    if (tv_truthy(tv_attr(tv_lookup(scope, "video_limit"), "error"))) {
        omt_buf_append(out, "\n    <p class=\"notice notice-warning\" role=\"status\">Saved video limit is invalid: ", 82);
        tv_render(out, tv_attr(tv_lookup(scope, "video_limit"), "error"));
        omt_buf_append(out, "</p>\n    ", 9);
    }
    omt_buf_append(out, "\n    ", 5);
    if (tv_truthy(tv_attr(tv_lookup(scope, "video_limit"), "above_board_default"))) {
        omt_buf_append(out, "\n    <p class=\"notice notice-warning\" role=\"status\">\n        This limit is above the ", 85);
        tv_render(out, tv_attr(tv_lookup(scope, "video_limit"), "board_label"));
        omt_buf_append(out, " default of\n        ", 20);
        tv_render(out, tv_attr(tv_lookup(scope, "video_limit"), "board_default_description"));
        omt_buf_append(out, ". This board may drop\n        frames instead of reporting an unsupported format.\n    </p>\n    ", 94);
    } else if (tv_truthy(tv_attr(tv_lookup(scope, "video_limit"), "overridden"))) {
        omt_buf_append(out, "\n    <p class=\"notice\" role=\"status\">\n        Overrides the ", 60);
        tv_render(out, tv_attr(tv_lookup(scope, "video_limit"), "board_label"));
        omt_buf_append(out, " default of\n        ", 20);
        tv_render(out, tv_attr(tv_lookup(scope, "video_limit"), "board_default_description"));
        omt_buf_append(out, ".\n    </p>\n    ", 15);
    }
    omt_buf_append(out, "\n    <form method=\"POST\" action=\"/system/video-limit\">\n        <input type=\"hidden\" name=\"csrf_token\" value=\"", 109);
    tv_render(out, tv_lookup(scope, "csrf_token"));
    omt_buf_append(out, "\">\n        <div class=\"field\">\n            <label for=\"video_limit\">Decode limit</label>\n            <input id=\"video_limit\" name=\"video_limit\"\n                   aria-describedby=\"video_limit_help\"\n                   placeholder=\"", 231);
    tv_render(out, tv_attr(tv_lookup(scope, "video_limit"), "board_default"));
    omt_buf_append(out, "\"\n                   value=\"", 28);
    tv_render(out, (tv_truthy(tv_attr(tv_lookup(scope, "video_limit"), "overridden")) ? tv_attr(tv_lookup(scope, "video_limit"), "effective") : &lit_10));
    omt_buf_append(out, "\">\n            <p class=\"field-help\" id=\"video_limit_help\">One or more WIDTHxHEIGHT@FPS\n               limits, separated by commas, such as\n               <code>1920x1080@30,1280x720@60</code>. Video is accepted when it fits\n               within any one of them. Leave empty to use this board's default of\n               ", 322);
    tv_render(out, tv_attr(tv_lookup(scope, "video_limit"), "board_default"));
    omt_buf_append(out, ".</p>\n        </div>\n        <button type=\"submit\" class=\"button\">Save video limit</button>\n    </form>\n</section>\n<section class=\"card danger-zone\" aria-labelledby=\"reboot-heading\">\n    <p class=\"eyebrow\">Danger zone</p>\n    <h2 id=\"reboot-heading\">Reboot operating system</h2>\n    <p>Rebooting stops playback and disconnects this Web GUI until the Raspberry Pi starts again.</p>\n    <div class=\"button-row\">\n        <a class=\"button button-danger\" href=\"/system/reboot\">Reboot OS\342\200\246</a>\n    </div>\n</section>\n", 511);
}

